import zipfile, re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('sales_data.xlsx') as z:
    print("Files in archive:")
    for n in z.namelist():
        print(" ", n)
    shared = None
    if 'xl/sharedStrings.xml' in z.namelist():
        shared = []
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))
    print("\nShared strings:", shared)
    wbroot = ET.fromstring(z.read('xl/workbook.xml'))
    for sheet in wbroot.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet'):
        print("sheet:", sheet.attrib)
    for name in z.namelist():
        if re.match(r'xl/worksheets/sheet\d+\.xml', name):
            root = ET.fromstring(z.read(name))
            print(f"\n--- {name} ---")
            sd = root.find('m:sheetData', NS)
            for row in sd.findall('m:row', NS):
                vals = []
                for c in row.findall('m:c', NS):
                    ref = c.attrib.get('r')
                    t = c.attrib.get('t')
                    v = c.find('m:v', NS)
                    val = v.text if v is not None else ''
                    if t == 's' and shared is not None:
                        try:
                            val = shared[int(val)]
                        except (ValueError, IndexError):
                            pass
                    vals.append(f"{ref}={val}")
                print(row.attrib.get('r'), vals)

